/*
 * GENERATED by gen_ref_manager.py - do not edit.
 *
 * The former stratum manager decision logic for the Rust tests. Every method
 * body was extracted verbatim from c-manager/stratum_manager*.cpp; tasks,
 * config, board, alerts and the system are mocks that record what it does.
 */
#include <algorithm>
#include <cstdint>
#include <cstring>

struct Actions {
    bool invalidate[2], disconnect[2], stop_timer[2], start_timer[2], connect[2], reset_verify_counts[2];
};
static Actions g_act;
static bool g_reconnect;

struct PThreadGuard {
    explicit PThreadGuard(int) {}
};

struct MockTask {
    int i = 0;
    bool connected = false;
    bool m_validNotify = false;
    void connect() { g_act.connect[i] = true; }
    void disconnect() { g_act.disconnect[i] = true; }
    void stopReconnectTimer() { g_act.stop_timer[i] = true; }
    void startReconnectTimer() { g_act.start_timer[i] = true; }
    void triggerReconnect() { g_reconnect = true; }
};

static void create_job_invalidate(int index) { g_act.invalidate[index] = true; }

struct Base {
    enum { PRIMARY = 0, SECONDARY = 1 };
    int m_mutex = 0;
    MockTask tasks[2];
    MockTask *m_stratumTasks[2] = {&tasks[0], &tasks[1]};
    bool blocked[2] = {};
    uint32_t m_verificationCheckCount[2] = {1, 1};
    uint32_t m_verificationFailCount[2] = {1, 1};
    bool isConnected(int i) { return m_stratumTasks[i] && m_stratumTasks[i]->connected; }
    bool isVerifyBlocked(int i) { return blocked[i]; }

    void prepare(bool has0, bool has1, bool c0, bool c1, bool b0, bool b1)
    {
        memset(&g_act, 0, sizeof(g_act));
        tasks[0].i = 0;
        tasks[1].i = 1;
        m_stratumTasks[0] = has0 ? &tasks[0] : nullptr;
        m_stratumTasks[1] = has1 ? &tasks[1] : nullptr;
        tasks[0].connected = c0;
        tasks[1].connected = c1;
        blocked[0] = b0;
        blocked[1] = b1;
        for (int i = 0; i < 2; i++) {
            m_verificationCheckCount[i] = m_verificationFailCount[i] = 1;
        }
    }
    Actions finish()
    {
        for (int i = 0; i < 2; i++) {
            g_act.reset_verify_counts[i] = m_verificationCheckCount[i] == 0 && m_verificationFailCount[i] == 0;
            // the former code cleared the valid-notify flag together with the invalidation
            if (g_act.invalidate[i] && tasks[i].m_validNotify) {
                g_act.invalidate[i] = false; // flag not cleared: report as a difference
            }
        }
        return g_act;
    }
};

struct RefFailover : Base {
    int m_selected = PRIMARY;
    void reconnectTimerCallback(int index)
{
    PThreadGuard lock(m_mutex);

    if (isVerifyBlocked(index)) return;

    // failover mode:
    if (index == PRIMARY) {
        // primary is always allowed to reconnect
        m_stratumTasks[index]->connect();
    } else {
        // secondary is only allowed if primary is NOT connected
        if (!isConnected(PRIMARY) || isVerifyBlocked(PRIMARY)) {
            m_stratumTasks[index]->connect();
        } else {
            // primary is good, we don't want secondary online
            m_stratumTasks[index]->disconnect();
        }
    }
}
    void connectedCallback(int index)
{
    PThreadGuard lock(m_mutex);

    // Blocked pool connected (e.g. after manual reconnect) — kick it off immediately
    if (isVerifyBlocked(index)) {
        m_stratumTasks[index]->disconnect();
        return;
    }

    if (index == PRIMARY) {
        // Primary is up → Secondary should go away (unless primary is blocked)
        m_selected = PRIMARY;
        m_verificationCheckCount[PRIMARY] = 0;  // fresh start when primary reconnects
        m_verificationFailCount[PRIMARY] = 0;

        if (m_stratumTasks[SECONDARY]) {
            m_stratumTasks[SECONDARY]->disconnect();
            m_stratumTasks[SECONDARY]->stopReconnectTimer();
        }
    } else { // index == SECONDARY
        // Secondary is up
        if (!isConnected(PRIMARY) || isVerifyBlocked(PRIMARY)) {
            // Primary is dead or blocked → accept Secondary as active
            m_selected = SECONDARY;
            m_verificationCheckCount[SECONDARY] = 0;  // fresh start when secondary takes over
            m_verificationFailCount[SECONDARY] = 0;
        } else {
            // Primary is alive and usable → we don't allow Secondary online
            m_stratumTasks[SECONDARY]->disconnect();
            m_stratumTasks[SECONDARY]->stopReconnectTimer();
        }
    }
}
    void disconnectedCallback(int index)
{
    PThreadGuard lock(m_mutex);
    create_job_invalidate(index);

    m_stratumTasks[index]->m_validNotify = false;

    if (index == PRIMARY) {
        // Primary went down -> allow secondary to try
        if (m_stratumTasks[SECONDARY]) {
            m_stratumTasks[SECONDARY]->startReconnectTimer();
            // m_stratumTasks[SECONDARY]->connect();
        }
        // m_selected will switch to SECONDARY once SECONDARY actually connects
    } else { // index == SECONDARY
        // Secondary went down. If Primary is still down too,
        // we might eventually reconnect SECONDARY anyway via its timer,
    }
}
};

struct BoardMock {
    uint32_t mn, mx;
    uint32_t getAsicMaxDifficulty() { return mx; }
    uint32_t getAsicMinDifficultyDualPool() { return mn; }
};
static BoardMock g_board;

struct RefDual : Base {
    typedef BoardMock Board;
    struct {
        BoardMock *getBoard() { return &g_board; }
    } SYSTEM_MODULE;
    int m_balance = 50;
    int32_t m_error_accum = 0;
    bool m_poolDiffErr[2]{};
    void reconnectTimerCallback(int index)
{
    PThreadGuard lock(m_mutex);

    // verify-blocked pool must not reconnect until the block is cleared
    if (isVerifyBlocked(index)) return;

    // dual pool: both pools always try to stay alive
    m_stratumTasks[index]->connect();
}
    void connectedCallback(int index)
{
    PThreadGuard lock(m_mutex);

    // Blocked pool connected (e.g. after settings save) — kick it off immediately
    if (isVerifyBlocked(index)) {
        m_stratumTasks[index]->disconnect();
        return;
    }

    // reset poolDiffErr
    if (index >= 0 && index < 2) {
        m_poolDiffErr[index] = false;
    }
}
    void disconnectedCallback(int index)
{
    PThreadGuard lock(m_mutex);
    create_job_invalidate(index);
    m_stratumTasks[index]->m_validNotify = false;
    m_stratumTasks[index]->startReconnectTimer();
}
    int getNextActivePool()
{
    PThreadGuard lock(m_mutex);
    int secondary_pct = 100 - m_balance;

    bool valid0 = m_stratumTasks[0] && m_stratumTasks[0]->m_validNotify && !isVerifyBlocked(0);
    bool valid1 = m_stratumTasks[1] && m_stratumTasks[1]->m_validNotify && !isVerifyBlocked(1);

    // fast paths: only one pool has valid work
    if (valid0 && !valid1) {
        m_error_accum = 0; // reset drift so wir nicht "Schuld" ansammeln
        return PRIMARY;
    }
    if (!valid0 && valid1) {
        m_error_accum = 0;
        return SECONDARY;
    }
    if (!valid0 && !valid1) {
        // nobody valid -> doesn't matter, but don't explode error
        m_error_accum = 0;
        return PRIMARY;
    }

    // dithering logic
    m_error_accum += secondary_pct; // accumulate pressure for SECONDARY

    if (m_error_accum >= 100) {
        // time to give SECONDARY a turn
        m_error_accum -= 100;
        return SECONDARY;
    }
    return PRIMARY;
}
    uint32_t selectAsicDiff(int pool, uint32_t poolDiff)
{
    Board *board = SYSTEM_MODULE.getBoard();
    uint32_t asicMax = board->getAsicMaxDifficulty();
    uint32_t asicMin = board->getAsicMinDifficultyDualPool();

    static uint32_t poolDiffs[2] = {0xffffffffu, 0xffffffffu};

    // shouldn't happen
    if (pool < 0 || pool >= 2) {
        return asicMax;
    }

    m_poolDiffErr[pool] = poolDiff < asicMin;

    poolDiffs[pool] = poolDiff;

    uint32_t minDiff = std::min(poolDiffs[0], poolDiffs[1]);

    // clamp to ASIC range
    if (minDiff < asicMin) {
        return asicMin;
    }
    if (minDiff > asicMax) {
        return asicMax;
    }
    return minDiff;
}
    int getActivePoolBalance(int pool)
{
    if (!m_stratumTasks[0] || !m_stratumTasks[1]) {
        return 0;
    }

    if (!isConnected(0) && !isConnected(1)) {
        return 0;
    }

    if (isConnected(0) && isConnected(1)) {
        return pool == 0 ? m_balance : 100 - m_balance;
    }

    return isConnected(pool) ? 100 : 0;

}
};

// --- coinbase verification ---
struct coinbase_result_t {
    uint64_t user_value_satoshis, total_value_satoshis;
    uint32_t block_height;
};
struct StratumConfigMock {
    const char *host;
    const char *getHost() { return host; }
};
static struct {
    uint16_t mode, max_fee;
    bool force;
} g_cfg;
struct Config {
    static uint16_t getCoinbaseVerifyMode(int) { return g_cfg.mode; }
    static uint16_t getCoinbaseMaxFee(int) { return g_cfg.max_fee; }
    static bool getCoinbaseVerifyForce(int) { return g_cfg.force; }
};
static bool g_alert;
static struct {
    void sendCoinbaseVerifyFailed(int, const coinbase_result_t *, int) { g_alert = true; }
} discordAlerter;
#define ESP_LOGW(...) ((void) 0)

struct RefVerify : Base {
    struct Board {
        enum Error { COINBASE_VERIFY_FAULT = 7 };
    };
    struct {
        int error = 0;
        void setBoardError(int e, int) { error = e; }
        int getBoardError() { return error; }
        void clearBoardError() { error = 0; }
    } SYSTEM_MODULE;
    coinbase_result_t m_coinbaseResult[2]{};
    bool m_verificationOk[2]{};
    const char *m_verifyBlockedReason[2]{};
    StratumConfigMock configs[2];
    StratumConfigMock *m_stratumConfig[2] = {&configs[0], &configs[1]};
    bool isVerifyBlocked(int pool) const { return m_verifyBlockedReason[pool] != nullptr; }
    void runVerification(int pool)
{
    const coinbase_result_t &cb = m_coinbaseResult[pool];

    uint16_t mode = Config::getCoinbaseVerifyMode(pool);

    // mode 0 = disabled, mode 1 = basic, mode 2 = extended
    if (mode == 0) {
        m_verificationOk[pool] = false;
        return;
    }

    // Basic (mode >= 1): user address must appear in coinbase
    bool ok = cb.user_value_satoshis > 0;

    // Extended (mode >= 2): additionally check pool fee does not exceed configured max
    if (ok && mode >= 2 && cb.total_value_satoshis > 0) {
        uint64_t pool_take = cb.total_value_satoshis - cb.user_value_satoshis;
        uint32_t fee_pct_x100 = (uint32_t)((pool_take * 10000ULL) / cb.total_value_satoshis);
        uint32_t max_fee_x100 = (uint32_t)Config::getCoinbaseMaxFee(pool) * 10;
        ok = fee_pct_x100 <= max_fee_x100;
    }

    // Send discord alert on transition to failed state
    if (!ok && m_verificationOk[pool]) {
        discordAlerter.sendCoinbaseVerifyFailed(pool, &cb, mode);
    }

    m_verificationCheckCount[pool]++;
    if (!ok) m_verificationFailCount[pool]++;
    // ESP_LOGE("runverify", "check count: %d, failed: %d, pool: %d", (int) m_verificationCheckCount[pool], (int) m_verificationFailCount[pool], (int) pool);

    m_verificationOk[pool] = ok;

    // Force mode: block this pool and check if any pool is still usable
    // Only act if we have actual coinbase data — skip if cache is empty (e.g. after settings save for new pool)
    if (Config::getCoinbaseVerifyForce(pool) && cb.block_height > 0) {
        if (!ok && !isVerifyBlocked(pool)) {
            const char *reason = (cb.user_value_satoshis == 0) ? "address_not_found" : "fee_exceeded";
            ESP_LOGW("stratum_manager", "Coinbase verification failed for pool %d (%s) - blocking", pool, reason);
            m_verifyBlockedReason[pool] = reason;
            if (m_stratumTasks[pool]) m_stratumTasks[pool]->triggerReconnect();
        } else if (ok && isVerifyBlocked(pool)) {
            m_verifyBlockedReason[pool] = nullptr;
        }

        // If all *configured* pools are verify-blocked, raise the fault flag so
        // the display shows an error. ASICs keep running on stale jobs until the
        // next block; no work will be submitted to a blocked pool.
        // (an unconfigured pool has no host and must not count as "usable")
        bool anyUsable = false;
        for (int i = 0; i < 2; i++) {
            bool configured = m_stratumConfig[i] && strlen(m_stratumConfig[i]->getHost()) > 0;
            if (configured && !isVerifyBlocked(i)) { anyUsable = true; break; }
        }
        if (!anyUsable) {
            ESP_LOGW("stratum_manager", "All pools blocked by verification - raising fault flag");
            SYSTEM_MODULE.setBoardError(Board::Error::COINBASE_VERIFY_FAULT, 0);
        } else if (SYSTEM_MODULE.getBoardError() == Board::Error::COINBASE_VERIFY_FAULT) {
            SYSTEM_MODULE.clearBoardError();
        }
    }
}
};

extern "C" {
static RefFailover s_fb;
static RefDual s_dp;

Actions ref_failover(int event, int pool, bool has0, bool has1, bool c0, bool c1, bool b0, bool b1, int *selected)
{
    s_fb.prepare(has0, has1, c0, c1, b0, b1);
    s_fb.tasks[pool & 1].m_validNotify = true;
    if (event == 0) s_fb.reconnectTimerCallback(pool);
    if (event == 1) s_fb.connectedCallback(pool);
    if (event == 2) s_fb.disconnectedCallback(pool);
    *selected = s_fb.m_selected;
    return s_fb.finish();
}

Actions ref_dual(int event, int pool, bool has0, bool has1, bool c0, bool c1, bool b0, bool b1, bool *diff_err)
{
    s_dp.prepare(has0, has1, c0, c1, b0, b1);
    s_dp.tasks[pool & 1].m_validNotify = true;
    if (event == 0) s_dp.reconnectTimerCallback(pool);
    if (event == 1) s_dp.connectedCallback(pool);
    if (event == 2) s_dp.disconnectedCallback(pool);
    diff_err[0] = s_dp.m_poolDiffErr[0];
    diff_err[1] = s_dp.m_poolDiffErr[1];
    return s_dp.finish();
}

// Each test starts from a fresh state (the selectAsicDiff() static is only
// used by one test).
void ref_reset()
{
    s_fb.m_selected = Base::PRIMARY;
    s_dp.m_balance = 50;
    s_dp.m_error_accum = 0;
    s_dp.m_poolDiffErr[0] = s_dp.m_poolDiffErr[1] = false;
}

int ref_dual_next(int balance, bool valid0, bool valid1, bool b0, bool b1)
{
    s_dp.prepare(true, true, true, true, b0, b1);
    s_dp.m_balance = balance;
    s_dp.tasks[0].m_validNotify = valid0;
    s_dp.tasks[1].m_validNotify = valid1;
    return s_dp.getNextActivePool();
}

uint32_t ref_dual_asic_diff(int pool, uint32_t diff, uint32_t mn, uint32_t mx, bool *diff_err)
{
    g_board = {mn, mx};
    uint32_t r = s_dp.selectAsicDiff(pool, diff);
    *diff_err = s_dp.m_poolDiffErr[pool & 1];
    return r;
}

int ref_dual_balance(int balance, int pool, bool has0, bool has1, bool c0, bool c1)
{
    s_dp.prepare(has0, has1, c0, c1, false, false);
    s_dp.m_balance = balance;
    return s_dp.getActivePoolBalance(pool);
}

struct VerifyOut {
    bool ok, counted, alert;
    unsigned char blocked;
    bool reconnect;
    int fault;
};

VerifyOut ref_verify(uint16_t mode, uint16_t max_fee, bool force, uint64_t user, uint64_t total, uint32_t height,
                     bool was_ok, unsigned char blocked, bool configured0, bool configured1, bool other_blocked,
                     int fault_before)
{
    RefVerify v; // fresh per call (its task/config pointers point into itself)
    g_cfg = {mode, max_fee, force};
    g_alert = false;
    g_reconnect = false;
    v.SYSTEM_MODULE.error = fault_before;
    v.m_coinbaseResult[0] = {user, total, height};
    v.m_verificationOk[0] = was_ok;
    v.m_verificationCheckCount[0] = 0;
    v.m_verifyBlockedReason[0] = blocked == 1 ? "address_not_found" : blocked == 2 ? "fee_exceeded" : nullptr;
    v.m_verifyBlockedReason[1] = other_blocked ? "fee_exceeded" : nullptr;
    v.configs[0].host = configured0 ? "pool" : "";
    v.configs[1].host = configured1 ? "pool" : "";
    v.runVerification(0);
    const char *r = v.m_verifyBlockedReason[0];
    return VerifyOut{v.m_verificationOk[0], v.m_verificationCheckCount[0] == 1, g_alert,
                     (unsigned char) (!r ? 0 : strcmp(r, "address_not_found") == 0 ? 1 : 2), g_reconnect,
                     v.SYSTEM_MODULE.error};
}
}
